','{}'::jsonb,true),
('lib/content/pa_scolarite/institution_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00413','Commentaire — R. 434-17',413,'string','• non respect délibéré des interdits alimentaires;
','• non respect délibéré des interdits alimentaires;
','{}'::jsonb,true),
('lib/content/pa_scolarite/institution_valeurs/deontologie/gpx_code_deontologie_commente_page.dart','f00414','Commentaire — R. 434-17',414,'string','• refus de fournir à la personne placée sous surveillance les médicaments prescrits par un médecin et nécessaires au traitement de sa pathologie.

